target = ".......((((.((((.(((.(((....))).(((.(((....))).(((.(((....))).(((.(((....))).(((......))).))).))).))).))).(....).)))).((((...(((.(((...((....))........))).(((.(((....)))(((....)))(((....)))))).)))...((((.(....).(((.(((.(((.(((.(((...(((....))).))).(((....))).))).(((....))).))).(((....))).))).((((((....)))(((....))).(((....)))))).))).))))...)))).))))......."

n=len(target)
stack=[]
pairs=[-1]*n
for i,c in enumerate(target):
    if c=='(':
        stack.append(i)
    elif c==')':
        j=stack.pop()
        pairs[j]=i; pairs[i]=j

seq=['A']*n  # ALL unpaired = A

# ALL stems pure GC, alternating G-C / C-G within each stem (no AU)
seen=set()
stems=[]
for i in range(n):
    if pairs[i]!=-1 and i not in seen and i<pairs[i]:
        k=0; members=[]
        while True:
            ii=i+k; jj=pairs[i]-k
            if pairs[ii]==jj and ii<jj and ii not in seen:
                members.append((ii,jj)); seen.add(ii); seen.add(jj); k+=1
            else: break
        stems.append(members)

for s in stems:
    for k,(i,j) in enumerate(s):
        if k%2==0:
            seq[i]='G'; seq[j]='C'
        else:
            seq[i]='C'; seq[j]='G'

result=''.join(seq)
print("LEN",len(result))
print(result)
